function safeClosest(el,selector){try{return el?.closest(selector)}catch{return null}}
/* BONON Website Studio: content, design, media, carousel and realtime. */
const fontChoices={dm:'DM Sans',manrope:'Manrope',playfair:'Playfair Display',anek:'Anek Bangla',tiro:'Tiro Bangla',noto:'Noto Sans Bengali'};
const CMS=window.CMS={config:null,admin:null,library:[],media:[],inspector:false,aliases:new Map(),styled:new WeakMap(),styleOriginals:new WeakMap(),discovered:new Map(),tab:'branding'};
CMS.set=function(cfg){this.config=cfg;this.aliases=new Map(Object.entries(L10N.dict).map(([en,bn])=>[bn,en]));for(const r of cfg.texts||[]){this.aliases.set(r.en,r.source);if(r.bn)this.aliases.set(r.bn,r.source);}this.applyDesign();};
function cssDeclarations(s){let str='';if(s.size)str+=`font-size:${s.size}px!important;`;if(s.line_height)str+=`line-height:${s.line_height}!important;`;if(s.letter_spacing!==undefined)str+=`letter-spacing:${s.letter_spacing}px!important;`;if(s.weight)str+=`font-weight:${s.weight}!important;`;if(s.color)str+=`color:${s.color}!important;`;if(s.background)str+=`background-color:${s.background}!important;`;if(s.font)str+=`font-family:'${fontChoices[s.font]}',sans-serif!important;`;if(s.italic!==undefined)str+=`font-style:${s.italic?'italic':'normal'}!important;`;if(s.radius!==undefined)str+=`border-radius:${s.radius}px!important;`;return str;}
CMS.applyDesign=function(){if(!this.config)return;const d=this.config.design,b=this.config.branding;let css=`html:not([data-theme=dark]){--ink:${d.text};--green:${d.accent};--muted:${d.muted};--paper:${d.background};--cms-surface:${d.surface};--cms-body-font:'${fontChoices[d.body_font]}';--cms-heading-font:'${fontChoices[d.heading_font]}';--cms-bn-body:'${fontChoices[d.bn_body_font]}';--cms-bn-heading:'${fontChoices[d.bn_heading_font]}'}html[data-theme=dark]{--paper:${d.dark_background};--ink:${d.dark_text};--cms-body-font:'${fontChoices[d.body_font]}';--cms-heading-font:'${fontChoices[d.heading_font]}';--cms-bn-body:'${fontChoices[d.bn_body_font]}';--cms-bn-heading:'${fontChoices[d.bn_heading_font]}'}body{font-size:${d.body_size}px}.btn{border-radius:${d.button_radius}px}.shop-intro h1,.story-hero h1{font-size:clamp(29px,4vw,${d.heading_size}px)}`;for(const r of d.rules||[]){css+=`${r.selector}{${cssDeclarations(r.style)}}`;if(r.style.mobile_size)css+=`@media(max-width:699px){${r.selector}{font-size:${r.style.mobile_size}px!important;}}`;}let el=document.getElementById('cms-design-tokens');if(!el){el=document.createElement('style');el.id='cms-design-tokens';document.head.append(el)}el.textContent=css;$('link[rel=icon]').attr('href',b.favicon||'/assets/favicon.svg');if(location.pathname.startsWith('/product/')){const productPage=S.products.find(p=>'/product/'+p.slug===location.pathname.replace(/\/$/,''));if(productPage)document.title=(L10N.lang==='bn'?productPage.name_bn:productPage.name)+' | '+b.name;}if(!location.pathname.startsWith('/product/')){if(!location.hash.startsWith('#admin'))document.title=b['title_'+L10N.lang];$('meta[name=description]').attr('content',b['description_'+L10N.lang]);$('meta[property="og:title"]').attr('content',b['title_'+L10N.lang]);$('meta[property="og:description"]').attr('content',b['description_'+L10N.lang]);}};
CMS.resolve=function(source,node){let trim=source.trim();const parent=node?.nodeType===1?node:node?.parentElement;const canonical=this.aliases.get(trim)||trim;if(S.user?.role==='admin'&&parent&&!parent.closest('.admin-shell,.modal,.cms-inspect-toolbar')&&trim.length>1&&trim.length<2000)this.discovered.set(canonical,{source:canonical,en:canonical,bn:L10N.dict[canonical]||''});let rule=null;if(parent&&!parent.closest('.admin-shell,.cms-studio-modal')){rule=[...(this.config?.texts||[])].reverse().find(r=>r.source===canonical&&(!r.scope||safeClosest(parent,r.scope)));}if(rule){if(parent){const old=this.styled.get(parent);if(old!==JSON.stringify(rule.style)+innerWidth){let style={...rule.style};if(innerWidth<=699&&style.mobile_size)style.size=style.mobile_size;if(!this.styleOriginals.has(parent))this.styleOriginals.set(parent,parent.getAttribute('style')||'');parent.style.cssText=this.styleOriginals.get(parent)+cssDeclarations(style);this.styled.set(parent,JSON.stringify(rule.style)+innerWidth);}}return source.replace(trim,L10N.lang==='bn'?(rule.bn||rule.en):rule.en);}if(parent&&this.styleOriginals.has(parent)){parent.style.cssText=this.styleOriginals.get(parent);this.styleOriginals.delete(parent);this.styled.delete(parent);}return L10N.lang==='bn'?translateText(source):source;};
const logoV2=logo;logo=()=>{const b=CMS.config?.branding;if(!b)return logoV2();return `<a class="brand ${b.logo_light?'image-brand':''}" href="/#home" data-route aria-label="${esc(b.name)}"><span class="brand-word" data-no-translate>${b.logo_light?`<img class="logo-light" src="${b.logo_light}" alt="${esc(b.name)}"><img class="logo-dark" src="${b.logo_dark||b.logo_light}" alt="${esc(b.name)}">`:esc(b.name.toLowerCase())}</span><span class="brand-tagline">${esc(b['tagline_'+L10N.lang])}</span></a>`};
function sliderMarkup(){const slides=CMS.config?.slides||[];if(!slides.length)return '';const lang=L10N.lang;return `<section class="hero wrap smart-hero" aria-label="${T('Featured collections','বিশেষ কালেকশন')}" tabindex="0"><div class="hero-slides">${slides.map((s,i)=>`<article class="hero-slide ${i===0?'is-active':''}" aria-hidden="${i!==0}" ${i?'inert':''}><div class="hero-art" style="background-image:url('${s.image}')"><picture>${s.mobile_image?`<source media="(max-width:699px)" srcset="${s.mobile_image}">`:''}<img src="${s.image}" alt="${esc(s['title_'+lang])}" ${i?'loading="lazy"':'fetchpriority="high"'}></picture></div><div class="hero-copy"><div class="eyebrow"><span></span>${esc(s['eyebrow_'+lang])}</div><h1>${esc(s['title_'+lang])}</h1><p>${esc(s['description_'+lang])}</p>${s['button_'+lang]?`<a href="${esc(s.button_url)}" data-route class="btn btn-dark">${esc(s['button_'+lang])}${I('arrow')}</a>`:''}</div><div class="craft-seal">${T('CRAFTED WITH CARE','যত্নে তৈরি')}<span>বুনন</span>${T('WORN WITH LOVE','ভালোবাসায় পরুন')}</div><div class="hero-caption">${T('THE ART OF EVERYDAY LIVING','প্রতিদিনের জীবনযাপনের শিল্প')}<span>EST. 2026</span></div></article>`).join('')}</div>${slides.length>1?`<div class="hero-carousel-controls"><div class="hero-dots" role="tablist" aria-label="${T('Choose slide','স্লাইড বাছাই করুন')}">${slides.map((s,i)=>`<button role="tab" data-slide-to="${i}" aria-label="${T('Slide','স্লাইড')} ${i+1}" aria-selected="${i===0}" class="${i===0?'active':''}"></button>`).join('')}</div><span class="hero-slide-counter" aria-live="off">01 / ${String(slides.length).padStart(2,'0')}</span><button data-slide-prev aria-label="${T('Previous slide','আগের স্লাইড')}">${I('arrow')}</button><button data-slide-next aria-label="${T('Next slide','পরের স্লাইড')}">${I('arrow')}</button><button data-slide-pause aria-label="${T('Pause slideshow','স্লাইড থামান')}">Ⅱ</button></div>`:''}</section>`;}
$.fn.bononCarousel=function(config={}){return this.each(function(){const $root=$(this),$slides=$root.find('.hero-slide');let index=0,timer=null,paused=false,startX=null;const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;const stop=()=>{clearInterval(timer);timer=null};function play(){stop();if(config.autoplay&&!paused&&!reduce&&!document.hidden&&$slides.length>1)timer=setInterval(()=>show(index+1),config.interval||6000)}function show(next){next=(next+$slides.length)%$slides.length;if(next===index)return;$slides.stop(true,true);$slides.eq(index).removeClass('is-active').attr('aria-hidden','true').prop('inert',true).fadeOut(reduce?0:380);index=next;$slides.eq(index).addClass('is-active').attr('aria-hidden','false').prop('inert',false).fadeIn(reduce?0:450);$root.find('[data-slide-to]').removeClass('active').attr('aria-selected','false').eq(index).addClass('active').attr('aria-selected','true');$root.find('.hero-slide-counter').text(String(index+1).padStart(2,'0')+' / '+String($slides.length).padStart(2,'0'));play()}
$root.on('click','[data-slide-next]',()=>show(index+1)).on('click','[data-slide-prev]',()=>show(index-1)).on('click','[data-slide-to]',function(){show(+$(this).data('slide-to'))}).on('click','[data-slide-pause]',function(){paused=!paused;$(this).text(paused?'▷':'Ⅱ').attr('aria-label',T(paused?'Play slideshow':'Pause slideshow',paused?'স্লাইড চালু করুন':'স্লাইড থামান'));play()});if(config.pause_hover)$root.on('mouseenter',stop).on('mouseleave',play);$root.on('focusin',stop).on('focusout',play).on('keydown',e=>{if(e.key==='ArrowRight'){e.preventDefault();show(index+1)}if(e.key==='ArrowLeft'){e.preventDefault();show(index-1)}}).on('touchstart',e=>{startX=e.originalEvent.touches[0].clientX;stop()}).on('touchend',e=>{const end=e.originalEvent.changedTouches[0].clientX;if(startX!==null&&Math.abs(end-startX)>45)show(index+(end<startX?1:-1));startX=null;play()});const visibility=()=>document.hidden?stop():play();document.addEventListener('visibilitychange',visibility);$root.data('carousel-destroy',()=>{stop();document.removeEventListener('visibilitychange',visibility);$root.off()});play()});};
function openMobileMenu(){const cats=[['Women','For her','category-women'],['Men','For him','category-men'],['Kids','For little ones','kids-1'],['Home & Living','For your home','home-1'],['Accessories','It’s all in the details','bag']];modal(`<div class="drawer-brand">${logo()}<span class="eyebrow">${T('YOUR EVERYDAY, BEAUTIFULLY WOVEN','আপনার প্রতিদিন, যত্নের বুননে')}</span></div><form class="drawer-search" id="drawer-search-form">${I('search')}<input name="q" placeholder="Find a little something you love…" aria-label="Search products"></form><a class="drawer-all" href="/#shop" data-route><span>${T('Discover the collection','কালেকশন দেখুন')}<small>${T('Thoughtful pieces for every day','প্রতিদিনের জন্য যত্নের পণ্য')}</small></span>${I('arrow')}</a><div class="drawer-category-list">${cats.map(([cat,sub,img])=>`<a href="/#shop?cat=${encodeURIComponent(cat)}" data-route><img src="/assets/${img}.jpg" alt=""><span><strong>${T(cat)}</strong><small>${T(sub)}</small></span>${I('chevron')}</a>`).join('')}</div><div class="drawer-secondary"><a href="/#shop?sort=new" data-route>${I('spark')}New arrivals<span>${T('JUST IN','নতুন')}</span></a><a href="/#shop?sale=1" data-route>${I('tag')}The good finds</a><a href="/#story" data-route>${I('leaf')}Our story</a><a href="/#wishlist" data-route>${I('heart')}Wishlist</a></div><div class="drawer-bottom"><button data-drawer-account>${I('user')}<span>${S.user?esc(S.user.name):T('Your little corner of BONON','বুননে আপনার আপন জায়গা')}<small>${S.user?T('Orders & your account','অর্ডার ও অ্যাকাউন্ট'):T('Sign in or create an account','লগইন বা অ্যাকাউন্ট তৈরি')}</small></span>${I('arrow')}</button>${appearanceControls()}</div>`,'mobile-nav-drawer');$('.overlay').addClass('nav-overlay');L10N.translate();}
document.addEventListener('click',e=>{if(e.target.closest('[data-action="mobile-menu"]')){e.preventDefault();e.stopImmediatePropagation();openMobileMenu()}if(e.target.closest('[data-action="notifications"]')){e.preventDefault();e.stopImmediatePropagation();openNotificationCenter()}},true);
$(document).on('submit','#drawer-search-form',function(e){e.preventDefault();go('/#shop?q='+encodeURIComponent(this.q.value))}).on('click','[data-drawer-account]',()=>{closeModal();if(S.user)go(S.user.role==='admin'?'/#admin':'/#account');else login()});
function productImages(p){return [...new Set([p.image,...(p.gallery||[])])].filter(Boolean)}
function mountGallery(p,selector){const images=productImages(p),$box=$(selector);if(!$box.length)return;$box.addClass('gallery-mounted').html(`<div class="zoom-stage" tabindex="0" role="button" aria-label="${T('Zoom product image','পণ্যের ছবি বড় করে দেখুন')}" data-gallery-id="${p.id}"><img class="zoom-main" src="${images[0]}" alt="${esc(p.name)}"><span class="product-tag">${T(p.tag||p.subcategory)}</span><span class="zoom-hint">${I('search')}${T('Hover to zoom · Tap on mobile','মাউস রাখুন বা ট্যাপ করে বড় দেখুন')}</span><button class="image-expand" data-image-expand="${p.id}" aria-label="${T('Open full image','সম্পূর্ণ ছবি খুলুন')}">${I('external')}</button></div><div class="gallery-thumbnails" role="list" aria-label="${T('Product images','পণ্যের ছবিগুলো')}">${images.map((im,i)=>`<button role="listitem" class="${i===0?'active':''}" data-gallery-index="${i}" data-gallery-product="${p.id}" aria-label="${T('View image','ছবি দেখুন')} ${i+1}" aria-pressed="${i===0}"><img src="${im}" alt="${esc(p.name)} — ${i+1}" loading="lazy"></button>`).join('')}<span class="gallery-count">${nfmt(images.length)} ${T('views','টি ছবি')}</span></div>`);$box.data('gallery-index',0);}
$(document).on('click','[data-gallery-index]',function(){const p=product(+$(this).data('gallery-product')),index=+$(this).data('gallery-index'),box=$(this).closest('.gallery-mounted');box.find('.zoom-main').attr('src',productImages(p)[index]);box.find('.zoom-stage').removeClass('touch-zoomed');box.find('.zoom-main').css({transform:'',transformOrigin:''});box.find('[data-gallery-index]').removeClass('active').attr('aria-pressed','false');$(this).addClass('active').attr('aria-pressed','true');box.data('gallery-index',index)});
$(document).on('mousemove','.zoom-stage',function(e){if(!matchMedia('(hover:hover)').matches)return;const r=this.getBoundingClientRect();$(this).find('.zoom-main').css({transform:'scale(2)',transformOrigin:`${(e.clientX-r.left)/r.width*100}% ${(e.clientY-r.top)/r.height*100}%`})}).on('mouseleave','.zoom-stage',function(){if(!$(this).hasClass('touch-zoomed'))$(this).find('.zoom-main').css({transform:'',transformOrigin:''})}).on('click','.zoom-stage',function(e){if(e.target.closest('[data-image-expand]'))return;if(matchMedia('(hover:none)').matches){$(this).toggleClass('touch-zoomed');$(this).find('.zoom-main').css({transform:$(this).hasClass('touch-zoomed')?'scale(2)':'',transformOrigin:'50% 50%'})}}).on('keydown','.zoom-stage',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();$(this).find('[data-image-expand]').trigger('click')}});
document.addEventListener('touchmove',e=>{const stage=e.target.closest('.zoom-stage.touch-zoomed');if(stage&&e.touches.length===1){e.preventDefault();const r=stage.getBoundingClientRect(),t=e.touches[0];stage.querySelector('.zoom-main').style.transformOrigin=`${Math.max(0,Math.min(100,(t.clientX-r.left)/r.width*100))}% ${Math.max(0,Math.min(100,(t.clientY-r.top)/r.height*100))}%`;}},{passive:false});
$(document).on('click','[data-image-expand]',function(e){e.stopPropagation();const p=product(+$(this).data('image-expand'));let index=$(this).closest('.gallery-mounted').data('gallery-index')||0;const imgs=productImages(p);modal(`<div class="lightbox-title"><span>${esc(p.name)}</span><small>${index+1} / ${imgs.length}</small></div><div class="lightbox-photo"><img src="${imgs[index]}" alt="${esc(p.name)}"></div><div class="lightbox-controls"><button class="btn btn-outline" data-lightbox-prev>${I('chevron')}</button><button class="btn btn-outline" data-lightbox-zoom>${I('plus')}${T('Zoom','জুম')}</button><button class="btn btn-outline" data-lightbox-next>${I('chevron')}</button></div>`,'product-lightbox');function swap(i){index=(i+imgs.length)%imgs.length;$('.lightbox-photo').removeClass('enlarged').find('img').attr('src',imgs[index]);$('.lightbox-title small').text(`${index+1} / ${imgs.length}`)}$('[data-lightbox-prev]').on('click',()=>swap(index-1));$('[data-lightbox-next]').on('click',()=>swap(index+1));$('[data-lightbox-zoom]').on('click',()=>$('.lightbox-photo').toggleClass('enlarged'));});
const productModalV2=productModal;productModal=function(id){productModalV2(id);const p=product(id);if(p)mountGallery(p,'.product-modal .detail-image')};
const studioTabs=[['branding','leaf','Brand & SEO','ব্র্যান্ড ও SEO'],['content','edit','Website text','ওয়েবসাইটের টেক্সট'],['design','spark','Design system','ডিজাইন কন্ট্রোল'],['slides','grid','Hero carousel','হিরো ক্যারোসেল'],['media','box','Media library','মিডিয়া লাইব্রেরি'],['realtime','bell','Live & notifications','লাইভ ও নোটিফিকেশন']];
function studioNav(){return `<div class="website-nav"><span class="sidebar-label">${T('YOUR WEBSITE','আপনার ওয়েবসাইট')}</span><nav>${studioTabs.map(([key,icon,en,bn])=>`<a href="/#admin/studio/${key}" data-route class="${CMS.tab===key&&location.hash.includes('/studio/')?'active':''}">${I(icon)}${T(en,bn)}</a>`).join('')}</nav></div>`}
function field(label,name,val,type='text',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(val??'')}" ${extra}></label>`}
function textArea(label,name,val,rows=3){return `<label>${label}<textarea name="${name}" rows="${rows}">${esc(val??'')}</textarea></label>`}
function fontSelect(label,name,val){return `<label>${label}<select name="${name}">${Object.entries(fontChoices).map(([k,v])=>`<option value="${k}" ${k===val?'selected':''}>${v}</option>`).join('')}</select></label>`}
function switchField(name,title,desc,value){return `<label class="studio-toggle"><span><strong>${title}</strong><small>${desc}</small></span><input name="${name}" type="checkbox" ${value?'checked':''}><i></i></label>`}
function mediaField(label,name,value,optional=false){const urls=CMS.media.map(i=>i.url);if(value&&!urls.includes(value))urls.unshift(value);return `<div class="media-field"><label>${label}</label><div class="media-field-body"><div class="media-field-preview">${value?`<img src="${value}" alt="${esc(label)}">`:I('box')}</div><div><select name="${name}" data-media-select ${optional?'':'required'}><option value="">${T('Choose an image','ছবি বেছে নিন')}</option>${urls.map(u=>`<option value="${u}" ${u===value?'selected':''}>${esc(u.split('/').pop())}</option>`).join('')}</select><label class="upload-label">${I('plus')}${T('Upload image','ছবি আপলোড')}<input type="file" accept="image/jpeg,image/png,image/webp" data-media-upload hidden></label><small>${T('JPG, PNG or WebP · Up to 2 MB','JPG, PNG বা WebP · সর্বোচ্চ ২ MB')}</small></div></div></div>`}
function studioFormHead(title,desc){return `<div class="studio-form-heading"><h3>${title}</h3><p>${desc}</p></div>`}
function studioFooter(){return `<div class="studio-save-bar"><span>${I('shield')}${T('Changes are saved to MySQL.','পরিবর্তন MySQL-এ সংরক্ষিত হয়।')}</span><p class="form-error"></p><button class="btn btn-dark" type="submit">${T('Save & publish','সংরক্ষণ ও প্রকাশ')}${I('check')}</button></div>`}
function studioContent(){const a=CMS.admin,tab=CMS.tab;const heading=studioTabs.find(t=>t[0]===tab);let html=`<div class="admin-heading studio-page-heading"><div><span class="eyebrow">${T('WEBSITE STUDIO','ওয়েবসাইট স্টুডিও')}</span><h1>${T(heading[2],heading[3])}</h1><p>${T('Your storefront. Your voice. Every little detail.','আপনার স্টোর। আপনার ভাষা। প্রতিটি খুঁটিনাটি।')}</p></div><div class="admin-heading-actions"><a href="/#home" data-route class="btn btn-outline">${I('external')}${T('View website','ওয়েবসাইট দেখুন')}</a><button class="btn btn-dark" data-visual-edit>${I('edit')}${T('Edit on page','পেজে সম্পাদনা')}</button></div></div><div class="studio-tabs">${studioTabs.map(([key,ic,en,bn])=>`<a href="/#admin/studio/${key}" data-route class="${tab===key?'active':''}">${I(ic)}${T(en,bn)}</a>`).join('')}</div>`;
if(tab==='branding'){const b=a.branding;return html+`<form id="branding-form" class="studio-form"><div class="studio-two-col"><div class="panel studio-panel">${studioFormHead(T('A familiar face. A beautiful first impression.','চেনা পরিচয়। সুন্দর প্রথম দেখায়।'),T('Logo, brand name and the little line beneath it.','লোগো, ব্র্যান্ডের নাম ও তার নিচের ছোট পরিচয়।'))}<div class="form-grid">${field(T('Brand name','ব্র্যান্ডের নাম'),'name',b.name)}${field(T('Tagline · English','ট্যাগলাইন · ইংরেজি'),'tagline_en',b.tagline_en)}${field(T('Tagline · Bengali','ট্যাগলাইন · বাংলা'),'tagline_bn',b.tagline_bn)}</div>${mediaField(T('Logo · Light theme','লোগো · লাইট থিম'),'logo_light',b.logo_light,true)}${mediaField(T('Logo · Dark theme','লোগো · ডার্ক থিম'),'logo_dark',b.logo_dark,true)}${mediaField(T('Browser favicon','ব্রাউজার ফ্যাভিকন'),'favicon',b.favicon,true)}</div><aside class="panel studio-panel brand-live-preview"><span class="eyebrow">${T('YOUR BRAND, AT A GLANCE','একনজরে আপনার ব্র্যান্ড')}</span><div class="brand-preview-light">${logo()}</div><div class="brand-preview-dark">${logo()}</div><div class="studio-tip">${I('leaf')}<p>${T('Transparent PNG logos look beautiful in both themes. Use a square image for the favicon.','স্বচ্ছ ব্যাকগ্রাউন্ডের PNG লোগো দুই থিমেই সুন্দর দেখায়। ফ্যাভিকনের জন্য বর্গাকার ছবি দিন।')}</p></div></aside></div><div class="panel studio-panel seo-panel">${studioFormHead(T('Be found. Be remembered.','খুঁজে পাক। মনে রাখুক।'),T('Control search results and the preview people see when your link is shared.','সার্চ রেজাল্ট এবং লিংক শেয়ারের প্রিভিউ নিয়ন্ত্রণ করুন।'))}<div class="form-grid">${field(T('Page title · English','পেজ টাইটেল · ইংরেজি'),'title_en',b.title_en)}${field(T('Page title · Bengali','পেজ টাইটেল · বাংলা'),'title_bn',b.title_bn)}${textArea(T('Meta description · English','মেটা বিবরণ · ইংরেজি'),'description_en',b.description_en)}${textArea(T('Meta description · Bengali','মেটা বিবরণ · বাংলা'),'description_bn',b.description_bn)}</div>${mediaField(T('Social sharing image','সোশ্যাল শেয়ার ছবি'),'social_image',b.social_image)}<label>${T('Search visibility','সার্চে দৃশ্যমানতা')}<select name="robots"><option value="index,follow" ${b.robots==='index,follow'?'selected':''}>${T('Allow search indexing','সার্চ ইনডেক্সিং চালু')}</option><option value="noindex,nofollow" ${b.robots==='noindex,nofollow'?'selected':''}>${T('Hide from search engines','সার্চ ইঞ্জিন থেকে লুকান')}</option></select></label><div class="search-preview"><span>${esc(location.origin)}</span><h4>${esc(b.title_en)}</h4><p>${esc(b.description_en)}</p></div></div>${studioFooter()}</form>`;}
if(tab==='content')return html+`<div class="studio-content-banner"><div>${I('edit')}<h3>${T('Every word should sound like you.','প্রতিটি কথায় থাকুক আপনার পরিচয়।')}</h3><p>${T('Search the text library, or click any text on your storefront to edit its English, Bengali and styling.','টেক্সট লাইব্রেরিতে খুঁজুন, অথবা স্টোরফ্রন্টের লেখায় ক্লিক করে ইংরেজি, বাংলা ও স্টাইল বদলান।')}</p></div><button class="btn btn-outline" data-new-text>${I('plus')}${T('Add text rule','নতুন টেক্সট রুল')}</button></div><section class="panel"><div class="admin-table-tools"><div class="table-search">${I('search')}<input id="cms-text-search" placeholder="${T('Search headings, buttons, labels…','হেডিং, বাটন বা লেবেল খুঁজুন…')}"></div><span class="cms-count"></span></div><div id="cms-text-list" class="cms-text-list"></div><div class="cms-list-footer"><button class="btn btn-outline" data-text-more>${T('Show more text','আরও টেক্সট দেখুন')}${I('plus')}</button></div></section>`;
if(tab==='design'){const d=a.design;return html+`<form id="design-form" class="studio-form"><div class="studio-two-col"><section class="panel studio-panel">${studioFormHead(T('Beautiful in every language.','প্রতিটি ভাষায় সুন্দর।'),T('A premium Bengali pairing: Tiro Bangla headlines with Anek Bangla body text.','সুন্দর বাংলা জুটি: হেডিংয়ে Tiro Bangla, মূল লেখায় Anek Bangla।'))}<div class="form-grid">${fontSelect(T('English body font','ইংরেজি মূল ফন্ট'),'body_font',d.body_font)}${fontSelect(T('English heading font','ইংরেজি হেডিং ফন্ট'),'heading_font',d.heading_font)}${fontSelect(T('Bengali body font','বাংলা মূল ফন্ট'),'bn_body_font',d.bn_body_font)}${fontSelect(T('Bengali heading font','বাংলা হেডিং ফন্ট'),'bn_heading_font',d.bn_heading_font)}${field(T('Base font size · px','মূল ফন্ট সাইজ · px'),'body_size',d.body_size,'number','min="12" max="24"')}${field(T('Heading size · px','হেডিং সাইজ · px'),'heading_size',d.heading_size,'number','min="24" max="80"')}${field(T('Button corner radius · px','বাটনের গোলাকার কোণ · px'),'button_radius',d.button_radius,'number','min="0" max="30"')}</div></section><aside class="panel typography-preview"><span class="eyebrow">${T('TYPE, WITH CHARACTER','লেখাতেও থাকুক নিজস্বতা')}</span><h2 class="bn-font-preview">নিজের শিকড়ের<br>আরও কাছে।</h2><p class="bn-body-preview">চেনা বুননে নতুন শুরু। আপনার প্রতিদিনের জন্য যত্নে বাছাই করা পণ্য।</p><div class="type-preview-divider"></div><h3 class="en-font-preview">Thoughtfully woven.<br>Beautifully you.</h3><p class="en-body-preview">Familiar threads. Fresh beginnings.</p></aside></div><section class="panel studio-panel palette-panel">${studioFormHead(T('A palette that feels like home.','নিজের মতো রঙের ছোঁয়া।'),T('Richer contrast in light mode. Calm, thoughtful colors after dark.','লাইট মোডে স্পষ্ট কনট্রাস্ট। ডার্ক মোডে শান্ত সুন্দর রং।'))}<div class="color-fields">${[['accent','Brand accent','ব্র্যান্ডের রং'],['text','Main text','মূল লেখার রং'],['muted','Secondary text','সহায়ক লেখার রং'],['background','Light background','লাইট ব্যাকগ্রাউন্ড'],['surface','Cards & panels','কার্ড ও প্যানেল'],['dark_background','Dark background','ডার্ক ব্যাকগ্রাউন্ড'],['dark_text','Dark text','ডার্ক লেখার রং']].map(([key,en,bn])=>`<label><input type="color" name="${key}" value="${d[key]}"><span>${T(en,bn)}<small data-color-label>${d[key]}</small></span></label>`).join('')}</div></section><section class="panel studio-panel">${studioFormHead(T('Fine-tune any part of your website.','ওয়েবসাইটের যেকোনো অংশ সাজান।'),T('Choose a component or CSS selector. Adjust desktop/mobile sizes, color, font, weight and spacing.','কম্পোনেন্ট বা CSS সিলেক্টর বেছে ডেস্কটপ/মোবাইল সাইজ, রং, ফন্ট ও স্পেসিং বদলান।'))}<div id="design-rules">${(d.rules||[]).map((r,i)=>designRule(r,i)).join('')}</div><button type="button" class="btn btn-outline" data-add-design-rule>${I('plus')}${T('Add a component style','কম্পোনেন্ট স্টাইল যোগ')}</button></section>${studioFooter()}</form>`;}
if(tab==='slides'){const c=a.carousel;return html+`<div class="carousel-studio-header"><div><h3>${T('A fresh story, with every slide.','প্রতিটি স্লাইডে নতুন গল্প।')}</h3><p>${T('Add campaigns, change images and write your own invitations.','ক্যাম্পেইন যোগ করুন, ছবি বদলান, আপনার ভাষায় আমন্ত্রণ জানান।')}</p></div><button class="btn btn-dark" data-new-slide>${I('plus')}${T('Add slide','স্লাইড যোগ')}</button></div><div class="slide-admin-grid">${a.slides.map((s,i)=>`<article class="slide-admin-card panel"><div class="slide-card-image"><img src="${s.image}" alt="${esc(s.title_en)}"><span class="product-tag">${s.active?T('Published','প্রকাশিত'):T('Hidden','লুকানো')}</span><span class="slide-number">${String(i+1).padStart(2,'0')}</span></div><div class="slide-card-copy"><span class="eyebrow">${esc(s['eyebrow_'+L10N.lang])}</span><h3>${esc(s['title_'+L10N.lang])}</h3><p>${esc(s['button_'+L10N.lang])} ${I('arrow')}</p><div class="slide-card-actions"><button class="text-link" data-edit-slide="${s.id}">${I('edit')}${T('Edit slide','স্লাইড সম্পাদনা')}</button><button class="icon-button" data-slide-up="${s.id}" aria-label="${T('Move earlier','আগে নিন')}" ${i===0?'disabled':''}>↑</button><button class="icon-button" data-delete-slide="${s.id}" aria-label="${T('Delete slide','স্লাইড মুছুন')}">${I('trash')}</button></div></div></article>`).join('')||`<div class="empty-state">${I('grid')}<h3>${T('Your next story starts here.','আপনার পরের গল্প এখানেই।')}</h3><button class="btn btn-dark" data-new-slide>${T('Add your first slide','প্রথম স্লাইড যোগ করুন')}</button></div>`}</div><form id="carousel-settings-form" class="panel studio-panel carousel-settings">${studioFormHead(T('A little motion. A lot of intention.','পরিমিত গতিতে সুন্দর অভিজ্ঞতা।'),T('Swipe on mobile, use arrow keys, or pause and take your time.','মোবাইলে সোয়াইপ করুন, অ্যারো ব্যবহার করুন, অথবা থামিয়ে দেখুন।'))}${switchField('autoplay',T('Automatic slideshow','স্বয়ংক্রিয় স্লাইড'),T('Advance slides automatically. Reduced-motion preferences are respected.','নিজে থেকে স্লাইড বদলাবে। ডিভাইসের reduced-motion সেটিং মানা হবে।'),c.autoplay)}${switchField('pause_hover',T('Pause on hover','মাউস রাখলে থামবে'),T('Let visitors read at their own pace.','দর্শককে নিজের মতো পড়ার সময় দিন।'),c.pause_hover)}${field(T('Time between slides · milliseconds','স্লাইডের বিরতি · মিলিসেকেন্ড'),'interval',c.interval,'number','min="3000" max="20000" step="500"')}${studioFooter()}</form>`;}
if(tab==='media')return html+`<section class="panel studio-panel"><div class="media-library-head"><div><h3>${T('Your visual world.','আপনার ছবির ভুবন।')}</h3><p>${T('Upload once. Use in your logo, carousel, social previews and products.','একবার আপলোড করে লোগো, ক্যারোসেল, সোশ্যাল প্রিভিউ ও পণ্যে ব্যবহার করুন।')}</p></div><label class="btn btn-dark upload-label">${I('plus')}${T('Upload images','ছবি আপলোড')}<input type="file" accept="image/jpeg,image/png,image/webp" multiple data-library-upload hidden></label></div><p class="media-security-note">${T('JPG, PNG, WebP · 2 MB per image · SVG and executable files are blocked for safety.','JPG, PNG, WebP · প্রতি ছবি ২ MB · নিরাপত্তার জন্য SVG ও executable ফাইল বন্ধ।')}</p><div id="media-library-grid" class="media-library-grid">${CMS.media.map(m=>`<button class="media-library-item" data-copy-media="${m.url}"><img src="${m.url}" alt="${esc(m.name)}" loading="lazy"><span>${esc(m.name)}</span><small>${Math.round(m.size/1024)} KB · ${T('Copy path','পাথ কপি')}</small></button>`).join('')}</div></section>`;
if(tab==='realtime'){const r=a.realtime,p=a.pusher_private;return html+`<form id="realtime-form" class="studio-form"><div class="connection-summary"><span class="connection-icon">${I('chart')}</span><div><h3>${T('A living, breathing storefront.','আপডেট থাকুক প্রতি মুহূর্তে।')}</h3><p>${T('Private Pusher channels with a polling safety net. No customer details on public channels.','প্রাইভেট Pusher চ্যানেল ও polling fallback। পাবলিক চ্যানেলে ক্রেতার ব্যক্তিগত তথ্য যায় না।')}</p></div><span class="transport-status" data-live-status>${T('Connecting…','সংযুক্ত হচ্ছে…')}</span></div><div class="studio-two-col"><section class="panel studio-panel">${studioFormHead(T('Live updates','লাইভ আপডেট'),T('Keep stock, orders and notifications up to date.','মজুত, অর্ডার ও নোটিফিকেশন আপডেট রাখুন।'))}${switchField('enabled',T('Enable live updates','লাইভ আপডেট চালু'),T('Master control for polling and Pusher connections.','Polling এবং Pusher-এর মূল কন্ট্রোল।'),r.enabled)}${field(T('Polling interval · seconds','Polling বিরতি · সেকেন্ড'),'poll_seconds',r.poll_seconds,'number','min="5" max="60"')}${switchField('new_order',T('New-order alerts','নতুন অর্ডার অ্যালার্ট'),T('Notify administrators when an order is placed.','নতুন অর্ডার এলে অ্যাডমিনকে জানান।'),r.new_order)}${switchField('order_status',T('Parcel & order updates','পার্সেল ও অর্ডারের খবর'),T('Notify each customer about their own order only.','শুধু সংশ্লিষ্ট ক্রেতাকে তার অর্ডারের খবর দিন।'),r.order_status)}${switchField('site_updates',T('Catalog & website refresh','ক্যাটালগ ও ওয়েবসাইট আপডেট'),T('Refresh changed content without interrupting a form.','ফর্মে কাজের সময় বাধা না দিয়ে পরিবর্তন দেখান।'),r.site_updates)}</section><section class="panel studio-panel">${studioFormHead(T('Browser notifications','ব্রাউজার নোটিফিকেশন'),T('Helpful updates, only with permission.','অনুমতি নিয়েই প্রয়োজনীয় আপডেট।'))}${switchField('browser_notifications',T('Allow browser notifications','ব্রাউজার নোটিফিকেশন চালু'),T('Visitors choose whether to allow notifications on their device.','ব্যবহারকারী তার ডিভাইসে অনুমতি দেবেন।'),r.browser_notifications)}<div class="browser-permission-card">${I('bell')}<h4>${T('This browser','এই ব্রাউজার')}</h4><p data-permission-status></p><button type="button" class="btn btn-outline" data-request-notifications>${T('Enable on this device','এই ডিভাইসে চালু করুন')}</button></div><p class="studio-disclaimer">${T('Browser alerts work while this site is open. Closed-tab/background Web Push is not included. Some mobile browsers require an installed web app and may not support this permission.','সাইট খোলা থাকলে ব্রাউজার অ্যালার্ট কাজ করে। বন্ধ ট্যাবে Web Push যুক্ত হয়নি। কিছু মোবাইল ব্রাউজারে ইনস্টল করা web app লাগে এবং এই অনুমতি নাও থাকতে পারে।')}</p></section></div><section class="panel studio-panel pusher-panel">${studioFormHead(T('Connect Pusher Channels','Pusher Channels সংযুক্ত করুন'),T('Copy these values from your Pusher app dashboard. App secrets stay on the server; changes saved here are encrypted.','আপনার Pusher ড্যাশবোর্ড থেকে তথ্য দিন। secret সার্ভারেই থাকে; এখানে সংরক্ষিত পরিবর্তন এনক্রিপ্টেড থাকে।'))}${switchField('pusher_enabled',T('Use Pusher for instant events','তাৎক্ষণিক ইভেন্টের জন্য Pusher'),T('Polling remains available if the socket disconnects.','সংযোগ বিচ্ছিন্ন হলে polling চালু থাকবে।'),r.pusher_enabled)}<div class="form-grid">${field('App ID','app_id',p.app_id,'text','inputmode="numeric" autocomplete="off"')}${field('App key','pusher_key',r.pusher_key,'text','autocomplete="off"')}<label>App secret<input name="secret" type="password" autocomplete="new-password" placeholder="${p.secret_set?T('Saved securely · leave blank to keep','নিরাপদে আছে · অপরিবর্তিত রাখতে ফাঁকা রাখুন'):T('Enter app secret','App secret লিখুন')}"></label><label>Cluster<select name="pusher_cluster">${['ap1','ap2','ap3','ap4','eu','us2','us3','us4','sa1','mt1'].map(c=>`<option value="${c}" ${c===r.pusher_cluster?'selected':''}>${c}</option>`).join('')}</select></label></div><div class="pusher-test-row"><button type="button" class="btn btn-outline" data-test-pusher>${I('chart')}${T('Test saved connection','সংরক্ষিত সংযোগ পরীক্ষা')}</button><span>${p.health?T('Last test: ','শেষ পরীক্ষা: ')+(p.health.ok?T('Accepted','গৃহীত'):T('Not connected','সংযুক্ত নয়')):T('No live Pusher connection tested yet.','এখনো লাইভ Pusher সংযোগ পরীক্ষা হয়নি।')}</span></div></section>${studioFooter()}</form>`;}
return html;}
function styleFields(s={}){return `<div class="style-fields">${field(T('Desktop · px','ডেস্কটপ · px'),'size',s.size||'','number','min="8" max="120"')}${field(T('Mobile · px','মোবাইল · px'),'mobile_size',s.mobile_size||'','number','min="8" max="80"')}<label>${T('Text color','লেখার রং')}<input name="color" value="${esc(s.color||'')}" placeholder="#344d3c" pattern="#[a-fA-F0-9]{6}"></label><label>${T('Weight','পুরুত্ব')}<select name="weight"><option value="">${T('Default','ডিফল্ট')}</option>${[300,400,500,600,700,800].map(v=>`<option ${String(s.weight)===String(v)?'selected':''}>${v}</option>`).join('')}</select></label><label>${T('Font family','ফন্ট')}<select name="font"><option value="">${T('Default','ডিফল্ট')}</option>${Object.entries(fontChoices).map(([k,v])=>`<option value="${k}" ${s.font===k?'selected':''}>${v}</option>`).join('')}</select></label>${field(T('Line height','লাইনের উচ্চতা'),'line_height',s.line_height||'','number','min="1" max="3" step="0.1"')}${field(T('Letter spacing','অক্ষরের দূরত্ব'),'letter_spacing',s.letter_spacing??'','number','min="-3" max="12" step="0.1"')}<label class="italic-check"><input type="checkbox" name="italic" ${s.italic?'checked':''}>${T('Italic','ইটালিক')}</label></div>`}
function designRule(r={},i=0){return `<div class="design-rule"><div class="design-rule-top"><label>${T('Component / CSS selector','কম্পোনেন্ট / CSS সিলেক্টর')}<input name="selector" list="component-selectors" value="${esc(r.selector||'')}" placeholder=".hero h1"></label><button type="button" class="icon-button" data-remove-rule aria-label="${T('Remove rule','রুল সরান')}">${I('trash')}</button></div>${styleFields(r.style||{})}<datalist id="component-selectors">${['.hero h1','.hero p','.product-title','.btn','.store-nav','.section-heading h2','.category-card h3','.footer','.price-line','.landing-info h1','.admin-main'].map(s=>`<option value="${s}">`).join('')}</datalist></div>`}
function allTextRows(){const map=new Map((CMS.admin?.text_library||[]).map(r=>[r.source,r]));for(const r of CMS.discovered.values())if(!map.has(r.source))map.set(r.source,r);for(const r of CMS.config?.texts||[])map.set(r.source,{...r,custom:true});return [...map.values()]}
function renderTextList(){const q=($('#cms-text-search').val()||'').toLowerCase();const rows=allTextRows().filter(r=>(r.source+' '+r.en+' '+r.bn).toLowerCase().includes(q));CMS.textRows=rows;CMS.textLimit??=40;$('.cms-count').text(nfmt(rows.length)+' '+T('text blocks','টি টেক্সট'));$('#cms-text-list').html(rows.slice(0,CMS.textLimit).map((r,i)=>`<button class="cms-text-row" data-edit-text="${i}"><div><span class="text-locale">EN</span><strong>${esc(r.en||r.source)}</strong></div><div><span class="text-locale">বাংলা</span><p>${esc(r.bn||T('Add a Bengali translation','বাংলা অনুবাদ যোগ করুন'))}</p></div><span class="text-edit-tag">${r.custom?T('Customized','সম্পাদিত'):T('Edit','সম্পাদনা')}${I('edit')}</span></button>`).join(''));$('[data-text-more]').toggle(CMS.textLimit<rows.length);}
function textEditor(r={},scope=''){const current=(CMS.config?.texts||[]).find(x=>x.source===r.source&&x.scope===scope)||r;modal(`<div class="editor-header"><span class="eyebrow">${T('MAKE EVERY WORD YOURS','প্রতিটি শব্দ হোক আপনার')}</span><h2>${T('A little change. Your own voice.','ছোট পরিবর্তন। আপনার নিজের ভাষা।')}</h2><p>${T('Plain text only. HTML and scripts are never executed.','শুধু লেখা। HTML বা স্ক্রিপ্ট চালানো হবে না।')}</p></div><form id="cms-text-form"><label>${T('Original text to match','যে মূল লেখাটি পরিবর্তন হবে')}<textarea name="source" rows="2" required ${r.source?'readonly':''}>${esc(current.source||'')}</textarea></label><div class="form-grid">${textArea('English','en',current.en||current.source||'',3)}${textArea('বাংলা','bn',current.bn||L10N.dict[current.source]||'',3)}</div><details class="text-style-details" open><summary>${T('Typography & style','ফন্ট ও স্টাইল')}</summary>${styleFields(current.style||{})}${field(T('Limit to a selector (optional)','শুধু এই সিলেক্টরে (ঐচ্ছিক)'),'scope',scope||current.scope||'')}<small>${T('Leave empty to update every matching text on the storefront.','ফাঁকা রাখলে স্টোরফ্রন্টে একই লেখা সব জায়গায় বদলাবে।')}</small></details><p class="form-error"></p><div class="form-actions">${current.id?`<button type="button" class="btn btn-outline" data-reset-text>${T('Restore original','মূল লেখা ফেরান')}</button>`:''}<button class="btn btn-dark" type="submit">${T('Save text & style','লেখা ও স্টাইল সংরক্ষণ')}${I('check')}</button></div></form>`,'editor-modal cms-studio-modal');}
function slideEditor(id){const s=CMS.admin.slides.find(s=>s.id===id)||{title_en:'',title_bn:'',eyebrow_en:'',eyebrow_bn:'',description_en:'',description_bn:'',button_en:'Shop now',button_bn:'এখনই কিনুন',button_url:'/#shop',image:'/assets/hero.jpg',mobile_image:'',position:CMS.admin.slides.length+1,active:1};modal(`<div class="editor-header"><span class="eyebrow">${T('TELL YOUR NEXT STORY','আপনার পরের গল্প বলুন')}</span><h2>${id?T('Refine your slide.','স্লাইড সাজান।'):T('A fresh little story.','নতুন একটি গল্প।')}</h2></div><form id="slide-form" data-id="${id||0}"><div class="form-grid">${field('Title · English','title_en',s.title_en,'text','required')}${field('শিরোনাম · বাংলা','title_bn',s.title_bn,'text','required')}${field('Eyebrow · English','eyebrow_en',s.eyebrow_en)}${field('উপরের ছোট শিরোনাম · বাংলা','eyebrow_bn',s.eyebrow_bn)}${textArea('Description · English','description_en',s.description_en)}${textArea('বিবরণ · বাংলা','description_bn',s.description_bn)}${field('Button · English','button_en',s.button_en)}${field('বাটনের লেখা · বাংলা','button_bn',s.button_bn)}${field(T('Button destination','বাটনের গন্তব্য'),'button_url',s.button_url)}${field(T('Display position','দেখানোর ক্রম'),'position',s.position,'number','min="0" max="1000"')}</div>${mediaField(T('Desktop image','ডেস্কটপের ছবি'),'image',s.image)}${mediaField(T('Mobile image · optional','মোবাইলের ছবি · ঐচ্ছিক'),'mobile_image',s.mobile_image,true)}${switchField('active',T('Publish this slide','এই স্লাইড প্রকাশ করুন'),T('Hidden slides stay in your studio.','লুকানো স্লাইড শুধু স্টুডিওতে থাকবে।'),s.active)}<p class="form-error"></p><div class="form-actions"><button type="button" class="btn btn-outline" data-action="close">Cancel</button><button class="btn btn-dark">${T('Save slide','স্লাইড সংরক্ষণ')}${I('check')}</button></div></form>`,'editor-modal slide-editor cms-studio-modal');}
function valuesWithChecks(form){const data=formData(form);$(form).find('input[type=checkbox]').each(function(){data[this.name]=this.checked});return data}
function readStyle(el){const s={};$(el).find('.style-fields').first().find('input,select').each(function(){if(this.type==='checkbox')s[this.name]=this.checked;else if(this.value!=='')s[this.name]=this.value});return s}
async function studioReload(){await refresh();await render();}
$(document).on('submit','#branding-form,#design-form,#carousel-settings-form,#realtime-form',async function(e){e.preventDefault();const form=this;submitting(form,true);const data=valuesWithChecks(form),action={'branding-form':'studio-branding','design-form':'studio-design','carousel-settings-form':'studio-carousel-save','realtime-form':'studio-realtime-save'}[form.id];if(form.id==='design-form')data.rules=$('#design-rules .design-rule').map(function(){return {selector:$(this).find('[name=selector]').val(),style:readStyle(this)}}).get();try{await api(action,data);await studioReload();toast(T('Saved. Your website has a little more of you.','সংরক্ষিত হয়েছে। ওয়েবসাইটে আপনার নিজের ছোঁয়া।'));if(action==='studio-realtime-save')Live.restart()}catch(e){submitting(form,false);fail(e)}});
$(document).on('submit','#cms-text-form',async function(e){e.preventDefault();submitting(this,true);try{await api('studio-text-save',{...formData(this),style:readStyle(this)});closeModal();await studioReload();toast(T('Your words are live.','আপনার লেখা প্রকাশিত হয়েছে।'))}catch(e){submitting(this,false);fail(e)}});
$(document).on('click','[data-reset-text]',async function(){const data=formData(document.getElementById('cms-text-form'));try{await api('studio-text-save',{source:data.source,scope:data.scope,reset:true});closeModal();await studioReload();toast(T('Original text restored.','মূল লেখা ফিরেছে।'))}catch(e){fail(e)}});
$(document).on('click','[data-new-text]',()=>textEditor()).on('click','[data-edit-text]',function(){textEditor(CMS.textRows[+$(this).data('edit-text')],CMS.textRows[+$(this).data('edit-text')].scope||'')}).on('input','#cms-text-search',()=>{CMS.textLimit=40;renderTextList()}).on('click','[data-text-more]',()=>{CMS.textLimit+=40;renderTextList()});
$(document).on('click','[data-add-design-rule]',()=>$('#design-rules').append(designRule())).on('click','[data-remove-rule]',function(){$(this).closest('.design-rule').remove()});
$(document).on('input change','#design-form input,#design-form select',function(){const f=document.getElementById('design-form'),d=valuesWithChecks(f);$('.bn-font-preview').css('font-family',fontChoices[d.bn_heading_font]);$('.bn-body-preview').css('font-family',fontChoices[d.bn_body_font]);$('.en-font-preview').css('font-family',fontChoices[d.heading_font]);$('.en-body-preview').css('font-family',fontChoices[d.body_font]);$('.typography-preview').css({color:d.text,background:d.background});$(this).siblings('span').find('[data-color-label]').text(this.value)});
$(document).on('click','[data-new-slide]',()=>slideEditor()).on('click','[data-edit-slide]',function(){slideEditor(+$(this).data('edit-slide'))});
$(document).on('submit','#slide-form',async function(e){e.preventDefault();submitting(this,true);try{await api('studio-slide-save',{...valuesWithChecks(this),id:+$(this).data('id')});closeModal();await studioReload();toast(T('Your slide is ready.','স্লাইড প্রস্তুত।'))}catch(e){submitting(this,false);fail(e)}});
$(document).on('click','[data-delete-slide]',function(){const id=+$(this).data('delete-slide');confirmAction(T('Remove this slide?','স্লাইডটি সরাবেন?'),T('Only this slide is removed. The image remains in your media library.','শুধু স্লাইডটি সরবে। ছবি মিডিয়া লাইব্রেরিতে থাকবে।'),async()=>api('studio-slide-delete',{id}))});
$(document).on('click','[data-slide-up]',async function(){const id=+$(this).data('slide-up'),list=CMS.admin.slides,i=list.findIndex(s=>s.id===id);if(i<=0)return;const x=list[i],y=list[i-1];try{await api('studio-slide-save',{...x,position:i-1});await api('studio-slide-save',{...y,position:i});await studioReload()}catch(e){fail(e)}});
async function uploadImage(file){const data=new FormData();data.append('image',file);return $.ajax({url:'/api?action=media-upload',method:'POST',data,processData:false,contentType:false,headers:{'X-CSRF-Token':BOOT.csrf}})}
$(document).on('change','[data-media-select]',function(){const field=$(this).closest('.media-field');field.find('.media-field-preview').html(this.value?`<img src="${this.value}" alt="">`:I('box'))});
$(document).on('change','[data-media-upload]',async function(){const file=this.files[0];if(!file)return;const field=$(this).closest('.media-field');field.addClass('uploading');try{const d=await uploadImage(file);CMS.media.unshift({url:d.url,name:file.name,size:file.size});field.find('select').append(`<option value="${d.url}">${esc(file.name)}</option>`).val(d.url).trigger('change');toast(T('Image uploaded. Save to publish.','ছবি আপলোড হয়েছে। প্রকাশ করতে সংরক্ষণ করুন।'))}catch(e){fail(e)}finally{field.removeClass('uploading');this.value=''}});
$(document).on('change','[data-library-upload]',async function(){this.disabled=true;try{for(const f of [...this.files].slice(0,12))await uploadImage(f);await studioReload();toast(T('Images added to your library.','ছবি লাইব্রেরিতে যোগ হয়েছে।'))}catch(e){fail(e)}finally{this.disabled=false}}).on('click','[data-copy-media]',function(){copyText($(this).data('copy-media'))});
const productEditorV2=productEditor;productEditor=async function(id){try{CMS.media=(await api('media-list')).items;}catch(e){fail(e);return}productEditorV2(id);const p=product(id),imgs=p?productImages(p):[];$('#product-form label').has('select[name=image]').remove();$('#product-form').data('gallery',imgs);$('#product-form .form-grid').after(`<section class="product-gallery-editor"><div class="studio-form-heading"><h3>${T('The full picture.','পণ্যের পুরো গল্প।')}</h3><p>${T('Add up to 12 photos. The first image is your cover. Move photos left or remove them.','সর্বোচ্চ ১২টি ছবি দিন। প্রথমটি প্রধান ছবি। বামে নিয়ে ক্রম বদলান বা সরিয়ে দিন।')}</p></div><div id="gallery-edit-thumbs"></div><div class="gallery-edit-actions"><label class="btn btn-outline upload-label">${I('plus')}${T('Upload product photos','পণ্যের ছবি আপলোড')}<input type="file" data-product-upload accept="image/jpeg,image/png,image/webp" multiple hidden></label><select data-add-gallery-media><option value="">${T('Add from media library','লাইব্রেরি থেকে যোগ করুন')}</option>${CMS.media.map(m=>`<option value="${m.url}">${esc(m.name)}</option>`).join('')}</select></div><input type="hidden" name="image"><input type="hidden" name="gallery"></section>`);updateGalleryEditor();};
function updateGalleryEditor(){const form=$('#product-form'),imgs=form.data('gallery')||[];$('#gallery-edit-thumbs').html(imgs.map((im,i)=>`<div><img src="${im}" alt="${T('Product photo','পণ্যের ছবি')} ${i+1}">${i===0?`<span>${T('COVER','প্রধান')}</span>`:''}<div><button type="button" data-gallery-move="${i}" ${i===0?'disabled':''} aria-label="${T('Move image left','ছবি বামে নিন')}">←</button><button type="button" data-gallery-remove="${i}" aria-label="${T('Remove image','ছবি সরান')}">${I('close')}</button></div></div>`).join(''));form.find('[name=gallery]').val(JSON.stringify(imgs));form.find('[name=image]').val(imgs[0]||'');}
function galleryEditorAdd(url){const f=$('#product-form'),a=f.data('gallery')||[];if(a.length>=12){toast(T('Use up to 12 images.','সর্বোচ্চ ১২টি ছবি দিন।'));return}if(!a.includes(url))a.push(url);f.data('gallery',a);updateGalleryEditor();}
$(document).on('change','[data-add-gallery-media]',function(){if(this.value)galleryEditorAdd(this.value);this.value=''}).on('click','[data-gallery-remove]',function(){const a=$('#product-form').data('gallery');a.splice(+$(this).data('gallery-remove'),1);updateGalleryEditor()}).on('click','[data-gallery-move]',function(){const a=$('#product-form').data('gallery'),i=+$(this).data('gallery-move');if(i>0)[a[i-1],a[i]]=[a[i],a[i-1]];updateGalleryEditor()}).on('change','[data-product-upload]',async function(){this.disabled=true;try{for(const f of [...this.files].slice(0,12)){if($('#product-form').data('gallery').length>=12)break;const d=await uploadImage(f,'product');galleryEditorAdd(d.url)}}catch(e){fail(e)}finally{this.value='';this.disabled=false}});
