function inspectorToolbar(){if(!CMS.inspector||S.user?.role!=='admin')return;$('.cms-inspect-toolbar').remove();$('body').addClass('cms-inspecting').append(`<div class="cms-inspect-toolbar">${I('edit')}<span>${T('Click a text to make it yours.','লেখায় ক্লিক করে নিজের মতো করুন।')}</span><a href="/#admin/studio/content" data-route>${T('Text library','টেক্সট লাইব্রেরি')}</a><button data-inspector-exit aria-label="${T('Exit editor','সম্পাদনা বন্ধ')}">${I('close')}</button></div>`)}
