const Live={timer:null,pusher:null,cursor:0,uid:null,busy:false,started:false,signature:'',unread:0,status:'polling',pollMs:10000,sw:null,readVersion:0};
function eventLabel(e){const p=e.payload||{},id=p.order_id?'#BN-'+String(p.order_id).padStart(4,'0'):'';if(e.type==='new-order')return {title:T('A new order has arrived.','নতুন অর্ডার এসেছে।'),body:id+' · '+money(p.total),url:'/#admin/orders'};if(e.type==='order-status')return {title:T('Your order has an update.','আপনার অর্ডারের নতুন খবর।'),body:id+' · '+T(p.status),url:'/#account'};if(e.type==='order-updated')return {title:T('Order updated','অর্ডার আপডেট হয়েছে'),body:id+' · '+T(p.status),url:'/#admin/orders'};return {title:T('A little update from BONON','বুননের নতুন খবর'),body:T('Your connection is working.','আপনার সংযোগ কাজ করছে।'),url:'/#account'};}
function permissionText(){if(!('Notification'in window))return T('Not supported in this browser.','এই ব্রাউজারে সমর্থিত নয়।');return {granted:T('Permission granted on this device.','এই ডিভাইসে অনুমতি আছে।'),denied:T('Blocked. Enable notifications in your browser’s site settings.','বন্ধ আছে। ব্রাউজারের সাইট সেটিংস থেকে অনুমতি দিন।'),default:T('Not enabled yet. Your permission is required.','এখনো চালু হয়নি। আপনার অনুমতি প্রয়োজন।')}[Notification.permission]}
