const NotificationSound={context:null,lastPlayed:0,memoryMuted:null,
 muted(){if(this.memoryMuted!==null)return this.memoryMuted;try{return localStorage.getItem('store-notification-muted')==='1'}catch(e){return false}},
 setMuted(value){this.memoryMuted=!!value;try{localStorage.setItem('store-notification-muted',value?'1':'0')}catch(e){}updateLiveUI()},
 unlock(){try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;this.context??=new Audio();if(this.context.state==='suspended')this.context.resume().catch(()=>{});}catch(e){}},
 play(test=false){if(this.muted())return;const ctx=this.context;if(!ctx||ctx.state!=='running')return;if(!test&&Date.now()-this.lastPlayed<900)return;this.lastPlayed=Date.now();try{const at=ctx.currentTime;[880,1174].forEach((frequency,i)=>{const oscillator=ctx.createOscillator(),gain=ctx.createGain(),start=at+i*.15;oscillator.type='sine';oscillator.frequency.value=frequency;gain.gain.setValueAtTime(0,start);gain.gain.linearRampToValueAtTime(.12,start+.015);gain.gain.exponentialRampToValueAtTime(.001,start+.2);oscillator.connect(gain);gain.connect(ctx.destination);oscillator.onended=()=>{oscillator.disconnect();gain.disconnect()};oscillator.start(start);oscillator.stop(start+.22);});}catch(e){}}
};
document.addEventListener('pointerdown',()=>NotificationSound.unlock(),{passive:true});
document.addEventListener('keydown',()=>NotificationSound.unlock());
window.addEventListener('storage',e=>{if(e.key==='store-notification-muted'){NotificationSound.memoryMuted=null;updateLiveUI()}});
function updateLiveUI(){const cfg=CMS.config?.realtime;const txt=!cfg?.enabled?T('Live updates paused','লাইভ আপডেট বন্ধ'):Live.status==='pusher'?T('Pusher connected','Pusher সংযুক্ত'):T('Polling active','Polling চালু');$('[data-live-status]').text(txt).toggleClass('connected',!!cfg?.enabled);$('[data-permission-status]').text(permissionText());$('.live-notification-count,.notification>i').remove();const unread=S.user?Math.max(0,Number(Live.unread)||0):0;$('.realtime-bell,.notification').attr('aria-label',T('Notifications','নোটিফিকেশন')+(unread?' · '+nfmt(unread)+' '+T('unread','অপঠিত'):''));if(unread>0)$('.realtime-bell,.notification').append(`<sup class="live-notification-count" aria-hidden="true">${unread>99?'99+':nfmt(unread)}</sup>`);const muted=NotificationSound.muted();$('[data-toggle-notification-sound]').attr('aria-pressed',String(muted)).text(muted?T('Sound: Off · Enable','শব্দ: বন্ধ · চালু করুন'):T('Sound: On · Mute','শব্দ: চালু · নীরব করুন'));$('[data-test-notification-sound]').prop('disabled',muted);}

Live.connect=function(){const cfg=CMS.config?.realtime;if(!cfg)return;const sig=JSON.stringify([cfg.enabled,cfg.pusher_enabled,cfg.pusher_key,cfg.pusher_cluster,S.user?.id,BOOT.csrf]);if(sig===this.signature)return;this.signature=sig;if(this.pusher){this.pusher.disconnect();this.pusher=null;}this.status='polling';if(!cfg.enabled||!cfg.pusher_enabled||!cfg.pusher_key){updateLiveUI();return}try{this.pusher=new Pusher(cfg.pusher_key,{cluster:cfg.pusher_cluster,forceTLS:true,channelAuthorization:{endpoint:'/api?action=pusher-auth',transport:'ajax',headers:{'X-CSRF-Token':BOOT.csrf}}});this.pusher.connection.bind('state_change',s=>{this.status=s.current==='connected'?'pusher':'polling';updateLiveUI()});const channels=['bonon-public'];if(S.user){channels.push('private-bonon-user-'+S.user.id);if(S.user.role==='admin')channels.push('private-bonon-admin');}channels.forEach(ch=>this.pusher.subscribe(ch).bind('bonon-event',event=>{if(event.type==='test'){toast(T('Pusher test received.','Pusher পরীক্ষা সফলভাবে এসেছে।'));return}this.poll()}));}catch(e){this.status='polling';updateLiveUI()}};
Live.showNotification=async function(e){const cfg=CMS.config?.realtime;if(!S.user||!cfg?.enabled||e.audience==='public')return;if((e.type==='new-order'&&!cfg.new_order)||(e.type==='order-status'&&!cfg.order_status))return;const key='bonon-notification-'+S.user.id;let last=Number(this.alertIds?.[key]||0);try{last=Math.max(last,Number(localStorage.getItem(key)||0))}catch(err){}if(Number(e.id)<=last)return;(this.alertIds??={})[key]=Number(e.id);try{localStorage.setItem(key,String(e.id))}catch(err){}const n=eventLabel(e);toast(n.title+' '+n.body);NotificationSound.play();let browserOn=false;try{browserOn=localStorage.getItem('bonon-browser-notifications')==='on'}catch(err){}if(!cfg.browser_notifications||!browserOn||!('Notification'in window)||Notification.permission!=='granted')return;try{if(this.sw){await this.sw.showNotification(n.title,{body:n.body,icon:CMS.config.branding.favicon||'/assets/favicon.svg',tag:'bonon-'+e.id,silent:true,data:{url:n.url}})}else{const notification=new Notification(n.title,{body:n.body,tag:'bonon-'+e.id,silent:true});notification.onclick=()=>{window.focus();go(n.url);notification.close()}}}catch(err){console.info('Browser notification unavailable; in-app notification retained.')}};
Live.poll=async function(){if(this.busy||S.authTransition)return;this.busy=true;const requestUser=String(S.user?.id??''),readVersion=this.readVersion;try{const initial=!this.started;const d=await api('realtime-poll&since='+this.cursor+(initial?'&initial=1':''));if(requestUser!==String(S.user?.id??'')||requestUser!==String(d.user_id??''))return;this.cursor=d.cursor;this.started=true;if(readVersion===this.readVersion)this.unread=d.unread;this.pollMs=d.config.poll_seconds*1000;if(CMS.config)CMS.config.realtime=d.config;this.connect();for(const e of d.events||[]){if(requestUser!==String(S.user?.id??''))break;if(!initial&&e.audience!=='public')await this.showNotification(e);}const changed=CMS.config&&d.revision!==CMS.config.revision;if(changed){const old=CMS.config.revision;const cfg=await api('studio-public');CMS.set(cfg);if(cfg.realtime.enabled&&cfg.realtime.site_updates){const editing=$('input:focus,textarea:focus,select:focus,.modal').length||$('#checkout-form,#branding-form,#design-form,#realtime-form').length;if(!editing&&!CMS.inspector){await refresh();if(location.hash.startsWith('#shop'))renderProducts();else if(location.hash.startsWith('#admin')&&!location.hash.includes('/studio'))await render();else if(!location.hash.startsWith('#account'))await render();}else{showRefreshPrompt()}}}if(d.events?.some(e=>e.type==='order-status')&&location.hash.startsWith('#account')&&!$('.modal,input:focus,textarea:focus').length){S.orders=(await api('my-orders')).orders;await render();}if(!d.config.enabled)this.status='paused';updateLiveUI();}catch(e){this.status='polling';}finally{this.busy=false;clearTimeout(this.timer);this.timer=setTimeout(()=>this.poll(),CMS.config?.realtime.enabled?this.pollMs:30000)}};
function showRefreshPrompt(){if($('.live-refresh-prompt').length)return;$('body').append(`<button class="live-refresh-prompt" data-refresh-live>${I('return')}${T('New updates available · Refresh when ready','নতুন আপডেট আছে · সুবিধামতো রিফ্রেশ করুন')}</button>`)}
Live.sync=function(){const id=S.user?.id||null;if(this.uid!==id){this.uid=id;this.cursor=0;this.started=false;this.signature='';this.unread=0;this.readVersion++;}this.connect();if(!this.timer&&!this.busy)this.poll();updateLiveUI()};Live.restart=function(){clearTimeout(this.timer);this.timer=null;this.signature='';this.connect();this.poll()};
